# Define transform based on pattern:
# For each n×n hollow frame, fill its interior with:
# - 7 if n is odd (3, 7, 9, 5, ...)
# - n//2 if n is even (4->2, 6->3)
def get_fill_value(n):
    return 7 if n % 2 == 1 else n // 2

def find_hollow_frames(grid):
    """Find all hollow square frames (n x n where n >= 3)"""
    frames = []
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            # Skip if this cell is part of another frame
            is_part_of_frame = False
            for fr_r, fr_c, fr_n, fr_color in frames:
                if fr_r <= r <= fr_r + fr_n - 1 and fr_c <= c <= fr_c + fr_n - 1:
                    # Check if on border
                    if (r == fr_r or r == fr_r + fr_n - 1 or c == fr_c or c == fr_c + fr_n - 1):
                        if grid[r][c] == fr_color:
                            is_part_of_frame = True
                            break
            if is_part_of_frame or color == 6 or color == 1:
                continue  # Skip background and other special colors

            # Try increasing sizes
            for n in range(max(3, 3), min(h-r+1, w-c+1)):
                # Check n×n hollow square
                is_hollow_square = True
                for i in range(n):
                    for j in range(n):
                        if i == 0 or i == n-1 or j == 0 or j == n-1:
                            if grid[r+i][c+j] != color:
                                is_hollow_square = False
                                break
                        else:
                            if grid[r+i][c+j] == color:
                                is_hollow_square = False
                                break
                    if not is_hollow_square:
                        break

                if is_hollow_square:
                    # Verify interior has different color than border
                    interior_h, interior_w = n-2, n-2
                    if interior_h > 0 and interior_w > 0:
                        for i in range(interior_h):
                            for j in range(interior_w):
                                if grid[r+1+i][c+1+j] == color:
                                    is_hollow_square = False
                                    break
                            if not is_hollow_square:
                                break

                    if is_hollow_square:
                        frames.append((r, c, n, color))
                        break
    return frames

